//
// plans/plan_xna_sample_xnb_sweep.md XNASWEEP-149: hand genuine XNA 4.0's
// MeshHelper.OptimizeForCache a generated family of small meshes and record exactly what order it
// puts their triangles in.
//
// The probes are generated by tools/xna-pipeline-oracle/optimize/generate.py into a flat text file
// so that this driver stays a transcriber rather than a second place where a topology is defined:
//
//   P <name> <shared:0|1> <positionCount> <faceCount>
//   V <x> <y> <z>          (positionCount of them)
//   F <a> <b> <c>          (faceCount of them, over position indices)
//
// and one line per probe comes back, `name|positionIndices|indices`, from which the emitted face
// order is a permutation of the input's.  Nothing here interprets the answer.

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Text;
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Content.Pipeline.Graphics;

internal static class OptimizeForCacheOracle
{
    private static int Main(string[] args)
    {
        if (args.Length < 2)
        {
            Console.Error.WriteLine("usage: OptimizeForCacheOracle <probes.txt> <out.txt>");
            return 2;
        }
        using (StreamReader reader = new StreamReader(args[0]))
        using (StreamWriter writer = new StreamWriter(args[1]))
        {
            string line;
            while ((line = reader.ReadLine()) != null)
            {
                line = line.Trim();
                if (line.Length == 0 || line[0] != 'P')
                    continue;
                string[] header = line.Split(' ');
                string name = header[1];
                bool shared = header[2] == "1";
                int positionCount = int.Parse(header[3], CultureInfo.InvariantCulture);
                int faceCount = int.Parse(header[4], CultureInfo.InvariantCulture);

                Vector3[] positions = new Vector3[positionCount];
                for (int i = 0; i < positionCount; i++)
                {
                    string[] parts = reader.ReadLine().Trim().Split(' ');
                    positions[i] = new Vector3(
                        float.Parse(parts[1], CultureInfo.InvariantCulture),
                        float.Parse(parts[2], CultureInfo.InvariantCulture),
                        float.Parse(parts[3], CultureInfo.InvariantCulture));
                }
                int[][] faces = new int[faceCount][];
                for (int i = 0; i < faceCount; i++)
                {
                    string[] parts = reader.ReadLine().Trim().Split(' ');
                    faces[i] = new int[] { int.Parse(parts[1], CultureInfo.InvariantCulture),
                                           int.Parse(parts[2], CultureInfo.InvariantCulture),
                                           int.Parse(parts[3], CultureInfo.InvariantCulture) };
                }

                string result;
                try
                {
                    MeshContent mesh = Build(name, positions, faces, shared);
                    MeshHelper.OptimizeForCache(mesh);
                    result = Describe(mesh);
                }
                catch (Exception error)
                {
                    result = "ERROR " + error.GetType().Name + ": " + error.Message.Replace('\n', ' ');
                }
                writer.WriteLine(name + "|" + result);
            }
        }
        return 0;
    }

    private static MeshContent Build(string name, Vector3[] positions, int[][] faces, bool shared)
    {
        MeshContent mesh = new MeshContent();
        mesh.Name = name;
        foreach (Vector3 position in positions)
            mesh.Positions.Add(position);
        GeometryContent geometry = new GeometryContent();
        mesh.Geometry.Add(geometry);
        List<int> vertices = new List<int>();
        List<int> indices = new List<int>();
        Dictionary<int, int> vertexOf = shared ? new Dictionary<int, int>() : null;
        foreach (int[] face in faces)
        {
            foreach (int corner in face)
            {
                int vertex;
                if (shared)
                {
                    if (!vertexOf.TryGetValue(corner, out vertex))
                    {
                        vertex = vertices.Count;
                        vertexOf[corner] = vertex;
                        vertices.Add(corner);
                    }
                }
                else
                {
                    vertex = vertices.Count;
                    vertices.Add(corner);
                }
                indices.Add(vertex);
            }
        }
        geometry.Vertices.AddRange(vertices.ToArray());
        geometry.Indices.AddRange(indices.ToArray());
        return mesh;
    }

    private static string Describe(MeshContent mesh)
    {
        StringBuilder text = new StringBuilder();
        GeometryContent geometry = mesh.Geometry[0];
        bool first = true;
        foreach (int index in geometry.Vertices.PositionIndices)
        {
            if (!first) text.Append(',');
            text.Append(index.ToString(CultureInfo.InvariantCulture));
            first = false;
        }
        text.Append('|');
        first = true;
        foreach (int index in geometry.Indices)
        {
            if (!first) text.Append(',');
            text.Append(index.ToString(CultureInfo.InvariantCulture));
            first = false;
        }
        return text.ToString();
    }
}
